static const char PAGE[] =
"<!doctype html><html lang='en'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
"<title>LibrePadPS5 Xbox experiment</title><style>body{max-width:760px;margin:40px auto;padding:16px;background:#111722;color:#eef2fa;font:16px system-ui}"
"button,select{font:inherit;padding:10px;margin:4px;background:#263549;color:#fff;border:1px solid #627288;border-radius:6px}button:disabled{opacity:.4}"
"pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#1b2636;padding:16px}p{line-height:1.5}</style>"
"<h1>LibrePadPS5 · Xbox Wireless</h1><p>Experimental native USB adapter support. Pair with the buttons on the adapter and controller."
" Keep the DualSense on its protected profile and use a separate signed-in user for Xbox input.</p>"
"<p id='status'>Loading…</p><p id='native'></p><select id='users' aria-label='Xbox user profile'></select>"
"<button id='bind' onclick='act(\"rebind?user=\"+el(\"users\").value)'>Assign profile</button>"
"<p><button id='reconnect' onclick='act(\"reconnect\")'>Reconnect</button><button id='home' onclick='act(\"home\")'>PS</button>"
"<button onclick='act(\"release\")'>Release</button><button onclick='logs()'>Read log</button><button onclick='act(\"stop\")'>Stop</button></p>"
"<p id='message'></p><pre id='log'>No log loaded.</pre><script>const el=id=>document.getElementById(id);let stopped=false;"
"async function refresh(){if(stopped)return;try{let s=await(await fetch('/api/status',{cache:'no-store'})).json();"
"el('status').textContent=(s.usb_connected?'Xbox controller connected':'Waiting for Xbox controller; inspect log for radio/firmware status')+' · Virtual pad '+(s.live?'active':'inactive')+' · Frames '+s.frames;"
"let selected=el('users').value;el('users').replaceChildren();for(let u of s.users){let o=document.createElement('option');o.value=u.id;o.textContent=u.name+(u.protected?' (protected DualSense)':'');o.disabled=u.protected;el('users').append(o);}"
"if(s.users.some(u=>u.id===selected&&!u.protected))el('users').value=selected;else if(s.users.some(u=>u.id===s.user&&!u.protected))el('users').value=s.user;"
"let target=s.users.find(u=>u.id===el('users').value);el('bind').disabled=!s.live||!target||target.protected||target.native_connected;"
"el('home').disabled=!s.live;el('reconnect').disabled=!s.usb_connected||s.status===1||s.status===2||s.live;"
"el('native').textContent='Protected profile: '+(s.users.find(u=>u.protected)?.name||'not configured');}catch(e){el('status').textContent='Dashboard offline';}}"
"async function act(path){try{let r=await fetch('/api/'+path,{method:'POST',headers:{'X-FreePad-Control':'1'}}),j=await r.json();el('message').textContent=j.message;"
"if(path==='stop'&&r.ok){stopped=true;el('status').textContent='Payload stopped';return;}await refresh();}catch(e){el('message').textContent=e.message;}}"
"async function logs(){try{el('log').textContent=await(await fetch('/api/log',{cache:'no-store'})).text();}catch(e){el('message').textContent=e.message;}}"
"refresh();setInterval(refresh,1000);</script></html>";
